afterInstall.code:
if (!function_exists('acf_pro_check_defined_license')) { fwrite(STDERR, "ACF PRO licensing functions are not loaded - is the plugin active?\n"); exit(1); }
if (!defined('ACF_PRO_LICENSE') || ACF_PRO_LICENSE === '') { fwrite(STDERR, "ACF_PRO_LICENSE is not defined on this site\n"); exit(1); }
if (function_exists('acf_pro_delete_license_transient')) { acf_pro_delete_license_transient('acf_activation_error'); }
acf_pro_check_defined_license();
if (function_exists('acf_pro_get_license_status')) { acf_pro_get_license_status(true); }
if (acf_pro_is_license_active()) { echo 'OK: license active for ' . home_url() . "\n"; exit(0); }
$fail = function_exists('acf_pro_get_activation_failure_transient') ? acf_pro_get_activation_failure_transient() : null;
$why = is_array($fail) && !empty($fail['error']) ? wp_strip_all_tags((string) $fail['error']) : 'license is not active after the activation attempt';
fwrite(STDERR, $why . "\n");
exit(1);

