beforeRemove.code:
if (!function_exists('acf_pro_deactivate_license')) { echo "ACF PRO is not loaded; nothing to release\n"; exit(0); }
$r = acf_pro_deactivate_license(true);
if (is_wp_error($r)) { fwrite(STDERR, $r->get_error_message() . "\n"); exit(1); }
if (is_array($r) && empty($r['success'])) { fwrite(STDERR, wp_strip_all_tags((string) ($r['message'] ?? 'deactivation failed')) . "\n"); exit(1); }
echo "OK: activation released\n";

verify.code:
if (!function_exists('acf_pro_is_license_active')) { fwrite(STDERR, "ACF PRO is not active on this site\n"); exit(1); }
if (function_exists('acf_pro_get_license_status')) { acf_pro_get_license_status(true); }
if (acf_pro_is_license_active()) { echo 'OK: license active for ' . home_url() . "\n"; exit(0); }
fwrite(STDERR, "license is not active\n");
exit(1);
